input.command:
PORT=$(node "c:/Users/russp/.vscode/extensions/emberstone-studio.tasker-1.4.0/tasker.js" port)
export PORT
CLAIMED=$(node << 'JSEOF'
const http=require('http');
const b=process.env.TASKER_TASK_ID?JSON.stringify({task_id:process.env.TASKER_TASK_ID}):'{}';
const req=http.request({hostname:'localhost',port:process.env.PORT,path:'/claim-ready',method:'POST',headers:{'Authorization':'Bearer '+(process.env.TASKER_ACTOR_TOKEN||''),'Content-Type':'application/json','Content-Length':Buffer.byteLength(b)}},res=>{
  let d='';
  res.on('data',c=>d+=c);
  res.on('end',()=>{
    try{const raw=JSON.parse(d);process.stdout.write(JSON.stringify(raw));}
    catch(e){process.stdout.write(JSON.stringify({error:e.message,tasks:[],agents:[]}));}
  });
});
req.on('error',e=>process.stdout.write(JSON.stringify({error:e.message,tasks:[],agents:[]})));
req.write(b);req.end();
JSEOF
)
echo "$CLAIMED"
